from pathlib import Path
import json,numpy as np,pandas as pd
ROOT=Path(__file__).resolve().parents[3];A=ROOT/'campaigns'/'CAM-0626'/'artifacts';OUT=A/'RUN-0012';c=pd.read_parquet(OUT/'order_capacity.parquet');c.date=pd.to_datetime(c.date);t=pd.read_parquet(A/'RUN-0010'/'trades.parquet');t.date=pd.to_datetime(t.date);z=t.merge(c[['date','symbol','fill_1000','fill_10000','fill_50000','fill_100000']],on=['date','symbol'],how='left',validate='one_to_one');days=pd.DataFrame({'date':pd.to_datetime(pd.read_parquet(A/'RUN-0010'/'passive_fills.parquet').date.unique())});rows=[]
